def audit_human_maintenance_delivery(action: str, summary: Any) -> dict[str, Any]:
    """Deterministically audit one Agent delivery summary without executing it."""

    errors: list[dict[str, Any]] = []
    contract = _ACTION_BY_NAME.get(str(action).strip())
    if contract is None:
        errors.append(_error("unknown-action", "未知 human maintenance action。", action=action))
        return {
            "schema_version": HUMAN_MAINTENANCE_PROMPT_SCHEMA_VERSION,
            "contract_version": HUMAN_MAINTENANCE_PROMPT_CONTRACT_VERSION,
            "registry_sha256": human_maintenance_registry_sha256(),
            "action": str(action),
            "status": "failed",
            "errors": errors,
        }
    if not isinstance(summary, Mapping):
        errors.append(_error("invalid-delivery-summary", "交付摘要必须是 JSON 对象。"))
        return {
            "schema_version": HUMAN_MAINTENANCE_PROMPT_SCHEMA_VERSION,
            "contract_version": HUMAN_MAINTENANCE_PROMPT_CONTRACT_VERSION,
            "registry_sha256": human_maintenance_registry_sha256(),
            "action": contract.action,
            "status": "failed",
            "errors": errors,
        }

    if summary.get("schema_version") != HUMAN_MAINTENANCE_PROMPT_SCHEMA_VERSION:
        errors.append(_error("schema-version-mismatch", "交付摘要 schema_version 不匹配。"))
    if summary.get("contract_version") != HUMAN_MAINTENANCE_PROMPT_CONTRACT_VERSION:
        errors.append(_error("contract-version-mismatch", "交付摘要 contract_version 不匹配。"))
    if summary.get("registry_sha256") != human_maintenance_registry_sha256():
        errors.append(_error("registry-hash-mismatch", "交付摘要 registry_sha256 不匹配。"))
    if summary.get("action") != contract.action:
        errors.append(_error("delivery-action-mismatch", "交付摘要必须返回同一 action。", expected=contract.action, actual=summary.get("action")))

    parameter_items, parameter_errors = _summary_parameter_items(contract, summary.get("parameters"))
    errors.extend(parameter_errors)
    validation = validate_human_maintenance_invocation(contract.action, parameter_items) if not parameter_errors else None
    if validation is not None and validation["status"] != "passed":
        errors.append(
            _error(
                "invalid-summary-parameters",
                "交付摘要 parameters 未通过同一 action 参数校验。",
                validation_errors=validation["errors"],
            )
        )
    parameters: Mapping[str, Any] = validation["parameters"] if validation and validation["status"] == "passed" else {}
    if parameters and dict(summary.get("parameters", {})) != dict(parameters):
        errors.append(_error("noncanonical-summary-parameters", "交付摘要 parameters 必须等于 Prompt 的规范化参数。"))
    if parameters and _is_placeholder(parameters):
        errors.append(_error("unresolved-parameter-slot", "实际交付摘要不得保留类型槽。"))

    active_steps = {
        step.step_id: step
        for step in active_command_steps(contract, parameters)
        if step.mapping == "existing-command"
    } if parameters else {}
    required_steps = {step_id for step_id, step in active_steps.items() if step.required_for_audit}
    commands = summary.get("commands")
    command_by_id: dict[str, Mapping[str, Any]] = {}
    if not isinstance(commands, list):
        errors.append(_error("invalid-command-evidence", "commands 必须是数组。"))
    else:
        for index, item in enumerate(commands):
            if not isinstance(item, Mapping):
                errors.append(_error("invalid-command-evidence", "每项 command evidence 必须是对象。", index=index))
                continue
            step_id = item.get("step_id")
            if not isinstance(step_id, str):
                errors.append(_error("missing-command-step-id", "command evidence 缺少 step_id。", index=index))
                continue
            if step_id in command_by_id:
                errors.append(_error("duplicate-command-evidence", "同一 step_id 不得重复。", step_id=step_id))
                continue
            if step_id not in active_steps:
                errors.append(_error("unexpected-command-evidence", "command evidence 不属于当前 action/parameters。", step_id=step_id))
                continue
            command_by_id[step_id] = item
        for step_id in sorted(required_steps - set(command_by_id)):
            errors.append(_error("missing-command-evidence", "缺少必需命令证据。", step_id=step_id))

    for step_id, item in command_by_id.items():
        step = active_steps[step_id]
        expected_command = render_step_command(step, parameters)
        if item.get("command") != expected_command:
            errors.append(_error("command-mismatch", "实际 command 与 Prompt 登记命令不一致。", step_id=step_id, expected=expected_command))
        expected_inputs = {name: parameters[name] for name in step.input_parameters if name in parameters}
        if item.get("inputs") != expected_inputs or not isinstance(item.get("inputs"), Mapping):
            errors.append(_error("command-inputs-mismatch", "命令 inputs 必须等于登记的规范参数。", step_id=step_id, expected=expected_inputs))
        exit_status = item.get("exit_status")
        if isinstance(exit_status, bool) or not isinstance(exit_status, int):
            errors.append(_error("missing-exit-status", "命令证据必须包含整数 exit_status。", step_id=step_id))
        elif exit_status not in step.allowed_exit_statuses:
            errors.append(
                _error(
                    "unexpected-exit-status",
                    "命令退出状态不在该步骤登记范围。",
                    step_id=step_id,
                    actual=exit_status,
                    allowed=list(step.allowed_exit_statuses),
                )
            )
        output_error = _literal_result_error(step, item.get("literal_output"))
        if output_error:
            errors.append(output_error)

    requirements = summary.get("requirements")
    if not isinstance(requirements, Mapping):
        errors.append(_error("invalid-requirement-evidence", "requirements 必须是对象。"))
    else:
        expected_names = {name for name, _state in contract.requirements}
        if set(requirements) != expected_names:
            errors.append(_error("requirement-set-mismatch", "requirements 字段集合必须与 action contract 完全一致。", expected=sorted(expected_names)))
        for name, declared_state in contract.requirements:
            state = _effective_requirement_state(contract, name, declared_state, parameters)
            item = requirements.get(name)
            if not isinstance(item, Mapping):
                errors.append(_error("missing-requirement-evidence", "缺少 requirement evidence。", requirement=name))
                continue
            status = item.get("status")
            evidence = item.get("evidence")
            if not isinstance(evidence, list):
                errors.append(_error("invalid-requirement-evidence", "requirement evidence 必须是数组。", requirement=name))
                continue
            if state == "required" and (status != "passed" or not evidence or _is_placeholder(evidence)):
                errors.append(_error("required-gate-not-passed", "required gate 必须有 passed 状态和实际证据。", requirement=name))
            elif state == "conditional" and status not in {"passed", "not-applicable"}:
                errors.append(_error("conditional-gate-invalid", "conditional gate 只能是 passed 或 not-applicable。", requirement=name))
            elif state == "conditional" and status == "passed" and (not evidence or _is_placeholder(evidence)):
                errors.append(_error("conditional-gate-missing-evidence", "通过的 conditional gate 必须有实际证据。", requirement=name))
            elif state == "not-required" and (status != "not-required" or evidence):
                errors.append(_error("not-required-gate-mismatch", "not-required gate 不得伪造通过证据。", requirement=name))
            elif state == "dependency" and (status != "dependency-ready" or not evidence or _is_placeholder(evidence)):
                errors.append(_error("dependency-gate-not-ready", "dependency gate 必须有 dependency-ready 状态和实际证据。", requirement=name))

    acceptance = summary.get("acceptance")
    expected_fields = set(contract.acceptance_summary_fields)
    if not isinstance(acceptance, Mapping):
        errors.append(_error("invalid-acceptance-summary", "acceptance 必须是对象。"))
    else:
        if set(acceptance) != expected_fields:
            errors.append(_error("acceptance-field-mismatch", "acceptance 字段集合必须与 action contract 完全一致。", expected=sorted(expected_fields)))
        for field in contract.acceptance_summary_fields:
            value = acceptance.get(field)
            if value is None or value == "" or _is_placeholder(value):
                errors.append(_error("missing-acceptance-value", "acceptance 字段必须包含实际值。", field=field))

    rollback = summary.get("rollback")
    expected_rollback = _expected_rollback(contract, parameters) if parameters else None
    if not isinstance(rollback, Mapping):
        errors.append(_error("invalid-rollback-summary", "rollback 必须是对象。"))
    elif expected_rollback is not None:
        if rollback.get("status") != expected_rollback["status"]:
            errors.append(_error("rollback-status-mismatch", "rollback status 与 action contract 不一致。"))
        if rollback.get("mapping") != expected_rollback["mapping"]:
            errors.append(_error("rollback-mapping-mismatch", "rollback mapping 与 action contract 不一致。"))
        if rollback.get("command") != expected_rollback["command"]:
            errors.append(_error("rollback-command-mismatch", "rollback command 与 action contract 不一致。"))
        evidence = rollback.get("evidence")
        rollback_requirement = _effective_rollback_requirement(contract, parameters)
        if rollback_requirement in {"required", "dependency"}:
            if not isinstance(evidence, list) or not evidence or _is_placeholder(evidence):
                errors.append(_error("rollback-evidence-missing", "required/dependency rollback 必须有实际准备证据。"))
        elif evidence not in ([], None):
            errors.append(_error("unexpected-rollback-evidence", "not-required rollback 不得伪造执行证据。"))

    return {
        "schema_version": HUMAN_MAINTENANCE_PROMPT_SCHEMA_VERSION,
        "contract_version": HUMAN_MAINTENANCE_PROMPT_CONTRACT_VERSION,
        "registry_sha256": human_maintenance_registry_sha256(),
        "action": contract.action,
        "status": "passed" if not errors else "failed",
        "checked_command_steps": sorted(command_by_id),
        "required_command_steps": sorted(required_steps),
        "errors": errors,
    }

def audit_human_maintenance_delivery_file(action: str, path: Path) -> dict[str, Any]:
    try:
        summary = json.loads(path.read_text(encoding="utf-8-sig"))
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        return {
            "schema_version": HUMAN_MAINTENANCE_PROMPT_SCHEMA_VERSION,
            "contract_version": HUMAN_MAINTENANCE_PROMPT_CONTRACT_VERSION,
            "registry_sha256": human_maintenance_registry_sha256(),
            "action": str(action),
            "status": "failed",
            "checked_command_steps": [],
            "required_command_steps": [],
            "errors": [_error("delivery-summary-read-failed", "无法读取结构化交付摘要。", detail=str(exc))],
        }
    return audit_human_maintenance_delivery(action, summary)

def _failed(operation: str, reason: str, message: str, **fields: Any) -> dict[str, Any]:
    return {
        "errors": [_error(reason, message, **fields)],
        "operation": operation,
        "schema_version": HUMAN_PAGE_AUTHORING_SCHEMA_VERSION,
        "status": "failed",
    }

def _missing(operation: str, page_type: str, mode: str, fields: Sequence[str]) -> dict[str, Any]:
    return {
        "missing_fields": sorted(set(fields)),
        "mode": mode,
        "operation": operation,
        "page_type": page_type,
        "schema_version": HUMAN_PAGE_AUTHORING_SCHEMA_VERSION,
        "status": "missing-fields",
    }

def _contract_result(
    operation: str,
    page_type: object,
    mode: object,
    *,
    contract_version: object = HUMAN_PAGE_TEMPLATE_CONTRACT_VERSION,
    schema_version: object = HUMAN_PAGE_TEMPLATE_SCHEMA_VERSION,
) -> tuple[HumanPageTemplateContract | None, dict[str, Any] | None]:
    mode_text = str(mode or "").strip()
    if mode_text not in HUMAN_PAGE_AUTHORING_MODES:
        return None, _failed(
            operation,
            "unknown-mode",
            f"未知人类页面编写模式：{mode_text}。",
            available=list(HUMAN_PAGE_AUTHORING_MODES),
        )
    try:
        contract_schema = int(schema_version)
    except (TypeError, ValueError):
        contract_schema = -1
    if (
        contract_schema != HUMAN_PAGE_TEMPLATE_SCHEMA_VERSION
        or str(contract_version) != HUMAN_PAGE_TEMPLATE_CONTRACT_VERSION
    ):
        return None, _failed(
            operation,
            "contract-version-incompatible",
            "人类页面模板合同版本不兼容；旧 1.0.0 输入必须显式按 V3 章节重写。",
            actual={"schema_version": schema_version, "contract_version": contract_version},
            expected={
                "schema_version": HUMAN_PAGE_TEMPLATE_SCHEMA_VERSION,
                "contract_version": HUMAN_PAGE_TEMPLATE_CONTRACT_VERSION,
            },
            migration={"from": "1.0.0", "to": HUMAN_PAGE_TEMPLATE_CONTRACT_VERSION, "mode": "explicit-rewrite"},
        )
    try:
        return get_human_page_template(str(page_type or "")), None
    except CkbError as exc:  # get_human_page_template owns the stable type list.
        return None, _failed(operation, "unknown-page-type", str(exc))

def _section_slot(section: SectionContract) -> dict[str, Any]:
    value: dict[str, Any] = {
        "human_summary": "",
        "key_entities": [],
        "links": [],
        "metrics": [],
        "source_refs": [],
        "machine_evidence_refs": [],
    }
    if section.heading_pattern:
        value["heading"] = ""
    return value

def _resolve_within(path_value: str | Path, workspace_root: str | Path) -> tuple[Path | None, dict[str, Any] | None]:
    root = Path(workspace_root).resolve()
    candidate = Path(path_value)
    if not candidate.is_absolute():
        candidate = root / candidate
    candidate = candidate.resolve()
    if candidate != root and root not in candidate.parents:
        return None, _failed(
            "inspect",
            "path-outside-workspace",
            "页面路径越过 workspace_root。",
            path=str(candidate),
            workspace_root=str(root),
        )
    if not candidate.is_file():
        return None, _failed("inspect", "source-not-found", "页面来源不是可读取文件。", path=str(candidate))
    return candidate, None

def _document_sections(markdown: str) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    lines = markdown.splitlines()
    headings: list[dict[str, Any]] = []
    fence: str | None = None
    for index, line in enumerate(lines):
        stripped = line.lstrip()
        marker = stripped[:3]
        if marker in {"```", "~~~"}:
            if fence is None:
                fence = marker
            elif marker == fence:
                fence = None
            continue
        if fence is not None:
            continue
        match = _HEADING_RE.match(line.strip())
        if match:
            headings.append(
                {"level": len(match.group(1)), "text": match.group(2).strip(), "line": index + 1, "index": index}
            )
    sections: list[dict[str, Any]] = []
    for position, heading in enumerate(headings):
        end = len(lines)
        for following in headings[position + 1 :]:
            if int(following["level"]) <= int(heading["level"]):
                end = int(following["index"])
                break
        body = "\n".join(lines[int(heading["index"]) + 1 : end]).strip()
        sections.append({**heading, "body": body, "end_index": end})
    return headings, sections

def _matches(section: SectionContract, heading: Mapping[str, Any]) -> bool:
    if int(heading["level"]) != section.level:
        return False
    text = str(heading["text"])
    if section.heading_pattern:
        return re.fullmatch(section.heading_pattern, text) is not None
    return text == section.heading

def _managed_source(path: Path, workspace_root: Path) -> bool:
    relative = path.resolve().relative_to(workspace_root.resolve())
    return bool({"human", "markdown"} & set(relative.parts)) or path.suffix.casefold() in {
        ".sqlite",
        ".db",
    }

def _non_empty(value: Any) -> bool:
    if isinstance(value, str):
        return bool(value.strip())
    if isinstance(value, (list, tuple, dict)):
        return bool(value)
    return value is not None

def _validate_top_level(payload: Mapping[str, Any], mode: str) -> dict[str, Any] | None:
    unknown = sorted(set(payload) - _MODE_FIELDS[mode])
    if unknown:
        return _failed(
            "render",
            "unknown-field",
            "schema 化输入包含未知字段。",
            fields=unknown,
        )
    return None

def _normalize_section_input(
    operation: str,
    section: SectionContract,
    value: Any,
) -> tuple[dict[str, Any] | None, dict[str, Any] | None]:
    if not isinstance(value, Mapping):
        return None, _failed(operation, "field-type-invalid", "章节输入必须是对象。", field=f"sections.{section.section_id}")
    allowed = {
        "human_summary",
        "key_entities",
        "links",
        "metrics",
        "source_refs",
        "machine_evidence_refs",
    }
    if section.heading_pattern:
        allowed.add("heading")
    unknown = sorted(set(value) - allowed)
    if unknown:
        return None, _failed(
            operation,
            "unknown-field",
            "章节输入包含未知字段。",
            fields=[f"sections.{section.section_id}.{name}" for name in unknown],
        )
    human_summary = str(value.get("human_summary") or "").strip()
    heading = str(value.get("heading") or section.heading).strip()
    if section.heading_pattern and heading and re.fullmatch(section.heading_pattern, heading) is None:
        return None, _failed(
            operation,
            "heading-pattern-mismatch",
            "动态章节标题不符合冻结合同。",
            field=f"sections.{section.section_id}.heading",
            pattern=section.heading_pattern,
        )
    lists: dict[str, list[Any]] = {}
    for field in ("key_entities", "links", "metrics", "source_refs", "machine_evidence_refs"):
        item = value.get(field, [])
        if not isinstance(item, list):
            return None, _failed(
                operation,
                "field-type-invalid",
                "章节的实体、指标、链接和证据引用字段必须是数组。",
                field=f"sections.{section.section_id}.{field}",
            )
        lists[field] = list(item)
    return {"human_summary": human_summary, "heading": heading, **lists}, None

def _section_validation_context(value: Mapping[str, Any]) -> dict[str, Any]:
    return {
        field: list(value.get(field, []))
        for field in ("key_entities", "links", "metrics", "source_refs", "machine_evidence_refs")
    }

def _canonical_reference(value: Mapping[str, Any]) -> dict[str, str]:
    result = {
        "kind": str(value.get("kind") or "").strip(),
        "purpose": str(value.get("purpose") or "").strip(),
        "target": str(value.get("target") or "").strip(),
    }
    digest = str(value.get("sha256") or "").strip().casefold()
    if digest:
        result["sha256"] = digest
    return result

def _section_evidence_document(
    contract: HumanPageTemplateContract,
    context: Mapping[str, Any],
) -> dict[str, Any]:
    sections_value = context.get("sections", {})
    assert isinstance(sections_value, Mapping)
    sections: list[dict[str, Any]] = []
    for section in contract.required_sections + contract.optional_sections:
        value = sections_value.get(section.section_id)
        if not isinstance(value, Mapping):
            continue
        source_refs = sorted(
            (_canonical_reference(item) for item in value.get("source_refs", []) if isinstance(item, Mapping)),
            key=lambda item: (item["target"], item["kind"], item["purpose"], item.get("sha256", "")),
        )
        machine_refs = sorted(
            (
                _canonical_reference(item)
                for item in value.get("machine_evidence_refs", [])
                if isinstance(item, Mapping)
            ),
            key=lambda item: (item["target"], item["kind"], item["purpose"], item.get("sha256", "")),
        )
        sections.append(
            {
                "disclosure_level": section.disclosure_level,
                "heading": section.heading,
                "machine_evidence_refs": machine_refs,
                "section_id": section.section_id,
                "source_refs": source_refs,
            }
        )
    return {"schema_version": 1, "sections": sections}

def _base_missing_fields(payload: Mapping[str, Any], contract: HumanPageTemplateContract) -> list[str]:
    missing: list[str] = []
    evidence = payload.get("evidence")
    if not isinstance(evidence, Mapping):
        missing.append("evidence")
    else:
        for field in contract.evidence_requirements.required_fields:
            if not _non_empty(evidence.get(field)):
                missing.append(f"evidence.{field}")
    context = payload.get("validation_context")
    if not isinstance(context, Mapping):
        missing.append("validation_context")
    return missing

def _load_source_for_render(
    payload: Mapping[str, Any], workspace_root: str | Path
) -> tuple[Path | None, str | None, dict[str, Any] | None]:
    source_value = payload.get("source_path")
    expected = str(payload.get("source_sha256") or "").casefold()
    missing = []
    if not _non_empty(source_value):
        missing.append("source_path")
    if not _SHA256_RE.fullmatch(expected):
        missing.append("source_sha256")
    if missing:
        return None, None, _missing("render", str(payload.get("page_type") or ""), str(payload.get("mode") or ""), missing)
    source, failure = _resolve_within(str(source_value), workspace_root)
    if failure:
        assert failure is not None
        failure["operation"] = "render"
        return None, None, failure
    assert source is not None
    try:
        markdown = source.read_text(encoding="utf-8-sig")
    except (OSError, UnicodeError) as exc:
        return None, None, _failed("render", "source-unreadable", f"页面来源读取失败：{exc}", path=str(source))
    actual = _sha256_text(markdown)
    if actual != expected:
        return None, None, _failed(
            "render",
            "target-drift",
            "页面来源在 inspect 后发生漂移。",
            expected_sha256=expected,
            actual_sha256=actual,
        )
    return source, markdown, None

def _validate_nested_input(
    operation: str,
    contract: HumanPageTemplateContract,
    evidence: Any,
    context: Any,
) -> dict[str, Any] | None:
    if not isinstance(evidence, Mapping):
        return None
    unknown_evidence = sorted(set(evidence) - set(contract.evidence_requirements.required_fields))
    if unknown_evidence:
        return _failed(
            operation,
            "unknown-field",
            "evidence 包含当前页面类型未定义的字段。",
            fields=[f"evidence.{field}" for field in unknown_evidence],
        )
    if not isinstance(context, Mapping):
        return None
    unknown_context = sorted(set(context) - _CONTEXT_FIELDS)
    if unknown_context:
        return _failed(
            operation,
            "unknown-field",
            "validation_context 包含未知字段。",
            fields=[f"validation_context.{field}" for field in unknown_context],
        )
    current_facts = context.get("current_facts", [])
    if isinstance(current_facts, list):
        for index, item in enumerate(current_facts):
            if not isinstance(item, Mapping):
                continue
            unknown = sorted(set(item) - {"claim", "source", "observed_at", "section_id"})
            if unknown:
                return _failed(
                    operation,
                    "unknown-field",
                    "validation_context.current_facts 条目包含未知字段。",
                    fields=[f"validation_context.current_facts[{index}].{name}" for name in unknown],
                )
    sections = context.get("sections", {})
    if isinstance(sections, Mapping):
        section_ids = set(_section_by_id(contract))
        unknown_sections = sorted(set(sections) - section_ids)
        if unknown_sections:
            return _failed(
                operation,
                "unknown-field",
                "validation_context.sections 包含当前页面类型未定义的章节。",
                fields=[f"validation_context.sections.{field}" for field in unknown_sections],
            )
        allowed_section = {"key_entities", "links", "metrics", "source_refs", "machine_evidence_refs"}
        for section_id, value in sections.items():
            if not isinstance(value, Mapping):
                continue
            unknown = sorted(set(value) - allowed_section)
            if unknown:
                return _failed(
                    operation,
                    "unknown-field",
                    "validation_context 章节条目包含未知字段。",
                    fields=[f"validation_context.sections.{section_id}.{name}" for name in unknown],
                )
            for field in ("links", "source_refs", "machine_evidence_refs"):
                entries = value.get(field, [])
                if not isinstance(entries, list):
                    continue
                for index, item in enumerate(entries):
                    if not isinstance(item, Mapping):
                        continue
                    unknown_ref = sorted(set(item) - {"target", "purpose", "kind", "sha256"})
                    if unknown_ref:
                        return _failed(
                            operation,
                            "unknown-field",
                            "章节链接或证据引用包含未知字段。",
                            fields=[
                                f"validation_context.sections.{section_id}.{field}[{index}].{name}"
                                for name in unknown_ref
                            ],
                        )
    return None

def _candidate_validation(
    contract: HumanPageTemplateContract,
    markdown: str,
    *,
    evidence: Any,
    context: Any,
    declared_boundary: Any,
) -> dict[str, Any]:
    missing: list[str] = []
    if not isinstance(evidence, Mapping):
        missing.append("evidence")
        evidence = {}
    for field in contract.evidence_requirements.required_fields:
        if not _non_empty(evidence.get(field)):
            missing.append(f"evidence.{field}")
    if not isinstance(context, Mapping):
        missing.append("validation_context")
        context = {}
    if missing:
        return _missing("validate", contract.page_type, "candidate", missing)

    base = validate_human_page(
        contract.page_type,
        markdown,
        context=context,
        contract_version=HUMAN_PAGE_TEMPLATE_CONTRACT_VERSION,
        schema_version=HUMAN_PAGE_TEMPLATE_SCHEMA_VERSION,
    )
    errors = list(base.get("errors", []))
    boundary_text = str(declared_boundary or "").strip()
    boundary_status = "passed"
    if boundary_text and boundary_text != contract.applicability_boundary:
        boundary_status = "failed"
        errors.append(
            _error(
                "applicability-boundary-drift",
                "输入适用边界与当前页面合同不一致。",
                expected=contract.applicability_boundary,
                actual=boundary_text,
            )
        )

    reasons = {str(error.get("reason")) for error in errors}

    def status_for(category: set[str]) -> str:
        return "failed" if reasons & category else "passed"

    checks = {
        "structure": {"status": status_for(_STRUCTURE_REASONS)},
        "budget": {
            "status": status_for(_BUDGET_REASONS),
            "key_entity_count": base.get("metrics", {}).get("key_entity_count"),
            "source_link_count": base.get("metrics", {}).get("source_link_count"),
        },
        "links": {"status": status_for(_LINK_REASONS)},
        "disclosure": {"status": status_for(_DISCLOSURE_REASONS)},
        "current_fact_evidence": {
            "status": status_for(_CURRENT_FACT_REASONS),
            "verified_count": base.get("metrics", {}).get("verified_current_fact_count"),
        },
        "contract_evidence": {
            "status": "passed",
            "required_fields": list(contract.evidence_requirements.required_fields),
        },
        "applicability_boundary": {
            "status": boundary_status,
            "value": contract.applicability_boundary,
        },
    }
    unclassified = reasons - _STRUCTURE_REASONS - _BUDGET_REASONS - _LINK_REASONS - _CURRENT_FACT_REASONS - _DISCLOSURE_REASONS - {
        "applicability-boundary-drift"
    }
    if unclassified:
        checks["validation_context"] = {"status": "failed", "reasons": sorted(unclassified)}
    else:
        checks["validation_context"] = {"status": "passed"}
    return {
        "checks": checks,
        "contract_version": HUMAN_PAGE_TEMPLATE_CONTRACT_VERSION,
        "errors": errors,
        "metrics": base.get("metrics", {}),
        "operation": "validate",
        "page_type": contract.page_type,
        "registry_sha256": human_page_template_registry_sha256(),
        "schema_version": HUMAN_PAGE_AUTHORING_SCHEMA_VERSION,
        "status": "passed" if not errors else "failed",
    }

def validate_page_author(payload: Mapping[str, Any]) -> dict[str, Any]:
    """Validate structure, budgets, links, evidence, and boundary in one result."""

    if not isinstance(payload, Mapping):
        return _failed("validate", "input-not-object", "validate 输入必须是 JSON 对象。")
    unknown = sorted(set(payload) - _VALIDATE_FIELDS)
    if unknown:
        return _failed(
            "validate",
            "unknown-field",
            "validate 输入包含未知字段。",
            fields=unknown,
        )
    contract, failure = _contract_result(
        "validate",
        payload.get("page_type"),
        "new",
        contract_version=payload.get("contract_version", HUMAN_PAGE_TEMPLATE_CONTRACT_VERSION),
        schema_version=payload.get("schema_version", HUMAN_PAGE_TEMPLATE_SCHEMA_VERSION),
    )
    if failure:
        return failure
    assert contract is not None
    failure = _validate_nested_input(
        "validate", contract, payload.get("evidence"), payload.get("validation_context")
    )
    if failure:
        return failure
    markdown = payload.get("markdown")
    if not isinstance(markdown, str) or not markdown.strip():
        return _missing("validate", contract.page_type, "candidate", ["markdown"])
    return _candidate_validation(
        contract,
        markdown,
        evidence=payload.get("evidence"),
        context=payload.get("validation_context"),
        declared_boundary=payload.get("applicability_boundary"),
    )
